/* v5.8.25 — material finish rules. User-approved per-model codes only. */
(function(){'use strict';
const PAINT_MRL=['Y033D','Y002B','Y116B','Y014B','Y055B'];
const CEILING_MRL=['Y135D','Y136D','Y055B'];
const LAM=['CP23','CP101','CP141','LA03','LA02'];
const MR_PAINT=['Y033','Y004','Y071','Y002','Y055','Y117','Y118','Y116','Y016','Y119','Y014'];
const INLINE_FINISH_IMAGES={'mr_y002':'data:image/jpeg;base64,','mr_y004':'data:image/jpeg;base64,','mr_y014':'data:image/jpeg;base64,','mr_y016':'data:image/jpeg;base64,','mr_y033':'data:image/jpeg;base64,','mr_y055':'data:image/jpeg;base64,','mr_y071':'data:image/jpeg;base64,','mr_y116':'data:image/jpeg;base64,','mr_y117':'data:image/jpeg;base64,','mr_y118':'data:image/jpeg;base64,','mr_y119':'data:image/jpeg;base64,','mrl_cp101':'data:image/jpeg;base64,','mrl_cp141':'data:image/jpeg;base64,','mrl_cp23':'data:image/jpeg;base64,','mrl_la02':'data:image/jpeg;base64,','mrl_la03':'data:image/jpeg;base64,','mrl_y002b':'data:image/jpeg;base64,','mrl_y014b':'data:image/jpeg;base64,','mrl_y033d':'data:image/jpeg;base64,','mrl_y055b':'data:image/jpeg;base64,','mrl_y116b':'data:image/jpeg;base64,','mrl_y133d':'data:image/jpeg;base64,','mrl_y134d':'data:image/jpeg;base64,','mrl_y135d':'data:image/jpeg;base64,','mrl_y136d':'data:image/jpeg;base64,','mrl_y137b':'data:image/jpeg;base64,'};
const NAMES={CP23:'Minimal stripe',CP101:'Silver',CP141:'Bright slate',LA03:'Washed oak',LA02:'Oiled walnut',Y033D:'White',Y002B:'Dark brown',Y116B:'Blue',Y014B:'Red-violet',Y055B:'Onyx black',Y135D:'Shadow white',Y136D:'Ash gray',Y033:'White',Y004:'Beige',Y071:'Neutral beige',Y002:'Dark brown',Y055:'Dark gray',Y117:'Lime green',Y118:'Light grayish blue',Y116:'Blue',Y016:'Light brown',Y119:'Carrot orange',Y014:'Red-violet'};
const groups={
 K22_CeilingColor:'ceiling',
 K23_WallPaintedColor:'paint',K24_CarDoorPaintedColor:'paint',K25_CarTransomPainted:'paint',K26_CarFrontPainted:'paint',
 K23_WallPattern:'lam',K24_CarDoorPattern:'lam',K25_CarTransomPattern:'lam',
 K23_WallFinish:'finish',K24_CarDoorFinish:'finish',K25_CarTransomFinish:'finish'
};
const old='Pattern-printed steel sheet PPS', fresh='Laminated steel sheet';
function patchFields(model,fields){if(model!=='MRL'||!fields)return;
 for(const f of fields){const kind=groups[f.name];if(!kind)continue;
 if(kind==='paint')f.options=[...PAINT_MRL];
 if(kind==='lam')f.options=[...LAM];
 if(kind==='ceiling')f.options=[...CEILING_MRL];
 if(kind==='finish')f.options=[...new Set((f.options||[]).map(x=>x===old?fresh:x))];
 if(typeof f.value==='string')f.value=f.value.replaceAll(old,fresh);
 if(typeof f.validation==='string')f.validation=f.validation.replaceAll(old,fresh);
 }
}
function patchDatabase(db){if(!db?.sheets?.DataTable)return db;
 if(db.__material5825)return db;
 const s=db.sheets.DataTable;
 // Update model-specific real DataTable rows used by its Excel-formula evaluator.
 s.A131=fresh;s.B131='Thép tấm phủ laminate';s.C131='Laminated steel sheet';
 // 5 laminate options, extend the pattern table by one cell (G129:G133).
 LAM.forEach((v,i)=>s['G'+(129+i)]=v);
 if(db.tables?.TblK26_Pattern)db.tables.TblK26_Pattern.ref='G128:G133';
 PAINT_MRL.forEach((v,i)=>s['E'+(129+i)]=v);
 for(let r=134;r<=139;r++)s['E'+r]='';
 // All old PPS literal comparisons in MRL formula expressions must use the new finish name.
 const convert=(val)=>typeof val==='string'?val.replaceAll(old,fresh):val&&typeof val==='object'&&typeof val.f==='string'?{...val,f:val.f.replaceAll(old,fresh)}:val;
 for(const [sheet,cells] of Object.entries(db.sheets||{}))for(const [key,v] of Object.entries(cells))if((typeof v==='string'&&v.includes(old))||(v&&typeof v==='object'&&typeof v.f==='string'&&v.f.includes(old)))cells[key]=convert(v);
 db.__material5825=true;return db;
}
function choices(model,field,prior){if(!field)return prior;
 const kind=groups[field.name];if(!kind)return prior;
 if(model==='MRL'){
 if(kind==='paint')return [...PAINT_MRL];
 if(kind==='lam')return [...LAM];
 if(kind==='ceiling'){
   // Ceiling source-specific restrictions remain authoritative for SUS / BN1 / DL6.
   return Array.isArray(prior)?prior.filter(x=>!/^Y\d/.test(x)||CEILING_MRL.includes(x)):prior;
 }
 if(kind==='finish')return [...new Set((prior||[]).map(x=>x===old?fresh:x))];
 }
 return prior; // MR follows its own original Excel validation. Preview only.
}
function check(model,fields,value){const rule=groups[fields?.name];if(!rule)return true;
 if(model==='MRL'){
  if(rule==='paint')return PAINT_MRL.includes(value);
  if(rule==='lam')return LAM.includes(value);
  if(rule==='ceiling'&&/^Y\d/.test(value))return CEILING_MRL.includes(value);
  if(rule==='finish')return value!==old;
 }
 return true;
}
function preview(model,field,value){const kind=groups[field?.name];if(!kind||!value)return null;
 const painted=(kind==='paint'||kind==='ceiling'&&/^Y\d/.test(value));
 const laminated=kind==='lam';if(!painted&&!laminated)return null;
 if(model==='MRL'){
  if(!check(model,field,value))return null;
  if(kind==='ceiling'&&!CEILING_MRL.includes(value))return null;
 }else if(model==='MR' && (!painted||!MR_PAINT.includes(value)))return null;
 const prefix=model==='MRL'?'mrl':'mr';
 return {src:INLINE_FINISH_IMAGES[prefix+'_'+value.toLowerCase()]||'',caption:NAMES[value]||value,approx:model==='MRL'&&['Y116B','Y014B'].includes(value)};
}
window.SPEC_MATERIAL_5825={PAINT_MRL,CEILING_MRL,LAM,MR_PAINT,patchFields,patchDatabase,choices,check,preview,fresh,old};
patchFields('MRL',window.SPEC_EMBEDDED?.MRL?.fields);
patchDatabase(window.SPEC_ENGINE_DATABASE?.MRL);
})();
